// Resource-oriented routing with the Go 1.22 mux: nouns in the path, verbs as methods.
func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users", listUsers)          // collection
	mux.HandleFunc("POST /users", createUser)        // create
	mux.HandleFunc("GET /users/{id}", getUser)       // single resource
	mux.HandleFunc("PUT /users/{id}", replaceUser)   // full replace
	mux.HandleFunc("PATCH /users/{id}", patchUser)   // partial update
	mux.HandleFunc("DELETE /users/{id}", deleteUser) // remove
	_ = http.ListenAndServe(":8080", mux)
}

func getUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id") // the noun's identity, never a verb
	fmt.Fprintf(w, "user %s", id)
}

// 201 + Location on create; 204 on delete; idempotent PUT replaces regardless of repeats.
func createUser(w http.ResponseWriter, r *http.Request) {
	id := store.Insert() // new resource
	w.Header().Set("Location", "/users/"+id)
	w.WriteHeader(http.StatusCreated) // 201, not 200
	_ = json.NewEncoder(w).Encode(map[string]string{"id": id})
}

func deleteUser(w http.ResponseWriter, r *http.Request) {
	store.Delete(r.PathValue("id")) // deleting twice leaves the same state (idempotent)
	w.WriteHeader(http.StatusNoContent) // 204, empty body
}

// URL versioning + query-based filtering on a collection.
func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/users", listUsers) // version in the path
	_ = http.ListenAndServe(":8080", mux)
}

func listUsers(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	status := q.Get("status")   // ?status=active
	sort := q.Get("sort")       // ?sort=-created_at (leading - = descending)
	users := store.Query(status, sort)
	_ = json.NewEncoder(w).Encode(users)
}

// Cursor pagination: fetch limit+1 rows after an opaque cursor to compute next_cursor.
func listOrders(w http.ResponseWriter, r *http.Request) {
	limit := 20
	cursor := r.URL.Query().Get("cursor") // opaque; here it's the last id seen

	// WHERE id > $cursor ORDER BY id LIMIT $limit+1  (index seek, not offset scan)
	rows := store.After(cursor, limit+1)

	var next string
	if len(rows) > limit { // extra row means there's another page
		next = rows[limit-1].ID
		rows = rows[:limit]
	}
	_ = json.NewEncoder(w).Encode(map[string]any{
		"data":        rows,
		"next_cursor": next, // empty when the list is exhausted
	})
}

// Spec-first with oapi-codegen: you author openapi.yaml, generate a ServerInterface,
// then implement it. The generated types keep handlers honest.

//go:generate oapi-codegen -generate types,server -package api openapi.yaml

// api.gen.go (generated) declares:
//   type ServerInterface interface { GetUser(w http.ResponseWriter, r *http.Request, id string) }
//   type User struct { ID string `json:"id"`; Name string `json:"name"` }

type Server struct{ store *Store }

// Implementing the generated interface = provably matching the spec.
func (s *Server) GetUser(w http.ResponseWriter, r *http.Request, id string) {
	u := s.store.Get(id) // returns the generated User type
	_ = json.NewEncoder(w).Encode(u)
}

// gqlgen author resolver backed by a dataloader to kill the N+1.
// Without the loader, resolving Author for N posts = N queries.
func (r *postResolver) Author(ctx context.Context, p *model.Post) (*model.User, error) {
	// Load() enqueues p.AuthorID; the loader batches all keys from this tick
	// into ONE query: SELECT * FROM users WHERE id IN (...).
	return dataloader.For(ctx).UserByID.Load(ctx, p.AuthorID)
}

// The batch function the loader calls once per tick with all collected keys.
func batchUsers(ctx context.Context, ids []string) ([]*model.User, []error) {
	users := store.UsersByIDs(ids) // single IN-query, results aligned to ids order
	return users, nil
}

