// APIError is the ONE error shape every endpoint returns.
type APIError struct {
	Code    string `json:"code"`    // machine-readable, e.g. "not_found"
	Message string `json:"message"` // human-readable
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status) // status FIRST, then the body
	_ = json.NewEncoder(w).Encode(map[string]APIError{
		"error": {Code: code, Message: msg},
	})
}

func getUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		writeError(w, http.StatusBadRequest, "invalid_request", "id is required")
		return
	}
	writeError(w, http.StatusNotFound, "not_found", "user does not exist")
}

package main

import (
	"encoding/json"
	"net/http"
	"strconv"
)

type Order struct {
	ID string `json:"id"`
}

type page struct {
	Data       []Order `json:"data"`
	NextCursor string  `json:"next_cursor"`
}

// after returns orders with ID strictly greater than cursor, ordered by ID.
func after(cursor string, n int) []Order {
	all := []Order{{"01"}, {"02"}, {"03"}, {"04"}, {"05"}}
	var out []Order
	for _, o := range all {
		if o.ID > cursor && len(out) < n {
			out = append(out, o)
		}
	}
	return out
}

func listOrders(w http.ResponseWriter, r *http.Request) {
	limit := 2
	if l := r.URL.Query().Get("limit"); l != "" {
		limit, _ = strconv.Atoi(l)
	}
	cursor := r.URL.Query().Get("cursor")

	rows := after(cursor, limit+1) // fetch one extra to detect a next page
	p := page{}
	if len(rows) > limit {
		p.NextCursor = rows[limit-1].ID // last kept row becomes the cursor
		rows = rows[:limit]
	}
	p.Data = rows
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(p)
}

package main

import (
