type User struct{ ID, Name string }
type Post struct{ ID, AuthorID string }

// NAIVE: called once per post -> N+1 queries.
func (r *resolver) AuthorNaive(ctx context.Context, p Post) (*User, error) {
	return r.store.UserByID(p.AuthorID), nil // 1 DB round trip PER post
}

// BATCHED: enqueue the key; the loader fires ONE query for all keys in the tick.
func (r *resolver) Author(ctx context.Context, p Post) (*User, error) {
	return loaderFor(ctx).Load(p.AuthorID)
}

// batchUsers is what the dataloader calls once with every collected key.
func (s *store) batchUsers(ids []string) []*User {
	fmt.Printf("SELECT * FROM users WHERE id IN %v\n", ids) // a SINGLE query
	out := make([]*User, len(ids))
	for i, id := range ids {
		out[i] = &User{ID: id, Name: "user-" + id}
	}
	return out
}

