package solution

// Paginate returns a page of items after cursor and the next cursor.
// next is "" when the list is exhausted.
func Paginate(all []string, cursor string, limit int) (data []string, next string) {
	if limit <= 0 {
		return nil, ""
	}
	// Fetch one extra to detect whether another page exists.
	for _, v := range all {
		if v > cursor && len(data) < limit+1 {
			data = append(data, v)
		}
	}
	if len(data) > limit { // the extra item means more remain
		next = data[limit-1] // last item we actually return
		data = data[:limit]  // trim the probe item
	}
	return data, next
}

