package solution

import (
	"reflect"
	"testing"
)

func TestPaginate(t *testing.T) {
	all := []string{"01", "02", "03", "04", "05"}

	d, n := Paginate(all, "", 2)
	if !reflect.DeepEqual(d, []string{"01", "02"}) || n != "02" {
		t.Fatalf("page1: got %v next %q", d, n)
	}

	d, n = Paginate(all, "02", 2)
	if !reflect.DeepEqual(d, []string{"03", "04"}) || n != "04" {
		t.Fatalf("page2: got %v next %q", d, n)
	}

	d, n = Paginate(all, "04", 2)
	if !reflect.DeepEqual(d, []string{"05"}) || n != "" {
		t.Fatalf("last page: got %v next %q (want no next)", d, n)
	}
}

