package solution

type User struct {
	ID   string
	Name string
}

// BatchUsers looks up all ids in one pass and returns results aligned to ids.
// A single lookup here replaces N separate per-item queries (kills N+1).
func BatchUsers(ids []string, db map[string]string) []*User {
	out := make([]*User, len(ids)) // aligned to ids; missing keys stay nil
	for i, id := range ids {
		if name, ok := db[id]; ok {
			out[i] = &User{ID: id, Name: name}
		}
	}
	return out
}

