package solution

import "testing"

func TestBatchUsers(t *testing.T) {
	db := map[string]string{"a": "Alice", "b": "Bob"}
	ids := []string{"a", "x", "b"}

	got := BatchUsers(ids, db)
	if len(got) != 3 {
		t.Fatalf("want 3 results aligned to ids, got %d", len(got))
	}
	if got[0] == nil || got[0].Name != "Alice" {
		t.Fatalf("ids[0]=a should be Alice, got %v", got[0])
	}
	if got[1] != nil {
		t.Fatalf("ids[1]=x is missing, must be nil, got %v", got[1])
	}
	if got[2] == nil || got[2].Name != "Bob" {
		t.Fatalf("ids[2]=b should be Bob, got %v", got[2])
	}
}

