// WriteJSON sets Content-Type and status BEFORE writing the body.
func WriteJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)             // status first...
	_ = json.NewEncoder(w).Encode(v)  // ...then stream the body
}

type apiError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func getUser(w http.ResponseWriter, r *http.Request) {
	u, ok := store.Get(r.PathValue("id"))
	if !ok {
		WriteJSON(w, http.StatusNotFound, map[string]apiError{
			"error": {Code: "not_found", Message: "user does not exist"},
		})
		return
	}
	WriteJSON(w, http.StatusOK, u)
}

// EncodeCursor packs (createdAt,id) into one opaque, URL-safe token.
func EncodeCursor(createdAt, id string) string {
	raw := createdAt + "\x00" + id // null-byte delimiter, unlikely in values
	return base64.RawURLEncoding.EncodeToString([]byte(raw))
}

// DecodeCursor reverses EncodeCursor and validates the shape.
func DecodeCursor(token string) (createdAt, id string, err error) {
	if token == "" {
		return "", "", nil // empty cursor = start of the collection
	}
	b, err := base64.RawURLEncoding.DecodeString(token)
	if err != nil {
		return "", "", fmt.Errorf("malformed cursor: %w", err)
	}
	parts := strings.SplitN(string(b), "\x00", 2)
	if len(parts) != 2 {
		return "", "", errors.New("malformed cursor: missing delimiter")
	}
	return parts[0], parts[1], nil
}
